import { GeoHorizon, type HorizonConnection } from "@/components/lumesec/geo-horizon";

const connections: HorizonConnection[] = [
  { from: { lat: 40.71, lon: -74.01 }, to: { lat: 51.51, lon: -0.13 } },
  { from: { lat: 38.72, lon: -9.14 }, to: { lat: 43.65, lon: -79.38 } },
  { from: { lat: 41.88, lon: -87.63 }, to: { lat: 50.11, lon: 8.68 } },
];

export function Hero() {
  return (
    <GeoHorizon aria-labelledby="hero-title" connections={connections} className="h-[480px]">
      <h1 id="hero-title" className="text-3xl font-semibold tracking-tight">
        Requests between regions
      </h1>
      <p className="text-muted-foreground">From the edge that receives a request to the region that answers it.</p>
    </GeoHorizon>
  );
}
